<?php

namespace App\Notifications;

use App\Notifications\Channels\DedupedDatabaseChannel;
use Illuminate\Notifications\Notification;

/**
 * In-app notification generated by real workflow events or the reminder command.
 * Email delivery is intentionally not enabled until mail is configured (see docs/SETUP_GUIDE.md).
 */
class AppAlert extends Notification
{
    public function __construct(
        public string $title,
        public string $url,
        public string $kind = 'info',
        public ?string $dedupeKey = null,
    ) {}

    public function via(object $notifiable): array
    {
        return [DedupedDatabaseChannel::class];
    }

    public function toArray(object $notifiable): array
    {
        return ['title' => $this->title, 'url' => $this->url, 'kind' => $this->kind];
    }
}
